"use strict";(self.webpackChunkshareme=self.webpackChunkshareme||[]).push([["391"],{54755(i){i.exports=JSON.parse('{"version":{"pluginId":"inverter","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/shareme/inverter/intro","label":"Kho t\xe0i li\u1EC7u cho bi\u1EBFn t\u1EA7n","docId":"intro","unlisted":false},{"type":"category","label":"Mitsubishi","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/shareme/inverter/mitsubishi/e720-mitsubishi","label":"E720","docId":"mitsubishi/e720-mitsubishi","unlisted":false},{"type":"link","href":"/shareme/inverter/mitsubishi/giam-sat-error","label":"Gi\xe1m s\xe1t l\u1ED7i bi\u1EBFn t\u1EA7n Mitsubishi","docId":"mitsubishi/giam-sat-error","unlisted":false},{"type":"link","href":"/shareme/inverter/mitsubishi/bang-tra-ma-loi-mitsubishi","label":"B\u1EA3ng tra c\u1EE9u m\xe3 l\u1ED7i","docId":"mitsubishi/bang-tra-ma-loi-mitsubishi","unlisted":false},{"type":"link","href":"/shareme/inverter/mitsubishi/truyen-thong-fx3u-bien-tan","label":"Truy\u1EC1n th\xf4ng FX3U & Bi\u1EBFn t\u1EA7n (485-BD)","docId":"mitsubishi/truyen-thong-fx3u-bien-tan","unlisted":false}],"href":"/shareme/inverter/category/mitsubishi"},{"type":"category","label":"OMRON","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/shareme/inverter/omron/mx2-omron","label":"3G3MX2","docId":"omron/mx2-omron","unlisted":false},{"type":"link","href":"/shareme/inverter/omron/jx-omron","label":"3G3JX","docId":"omron/jx-omron","unlisted":false},{"type":"link","href":"/shareme/inverter/omron/error-codes-omron","label":"B\u1EA3ng m\xe3 l\u1ED7i & Kh\u1EAFc ph\u1EE5c","docId":"omron/error-codes-omron","unlisted":false}],"href":"/shareme/inverter/category/omron"},{"type":"category","label":"WECON","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/shareme/inverter/wecon/wecon-manual","label":"H\u01B0\u1EDBng d\u1EABn s\u1EED d\u1EE5ng WECON VM","docId":"wecon/wecon-manual","unlisted":false},{"type":"link","href":"/shareme/inverter/wecon/parameter-configuration-wecon","label":"B\u1EA3ng tham s\u1ED1 c\xe0i \u0111\u1EB7t (F0 - FD)","docId":"wecon/parameter-configuration-wecon","unlisted":false},{"type":"link","href":"/shareme/inverter/wecon/error-codes-wecon","label":"B\u1EA3ng m\xe3 l\u1ED7i & Kh\u1EAFc ph\u1EE5c (ERR02-22)","docId":"wecon/error-codes-wecon","unlisted":false},{"type":"link","href":"/shareme/inverter/wecon/registers-rs485-wecon","label":"Truy\u1EC1n th\xf4ng Modbus RS-485","docId":"wecon/registers-rs485-wecon","unlisted":false}],"href":"/shareme/inverter/category/wecon"}]},"docs":{"intro":{"id":"intro","title":"Kho t\xe0i li\u1EC7u cho bi\u1EBFn t\u1EA7n","description":"\u0110ang c\u1EADp nh\u1EADt...","sidebar":"tutorialSidebar"},"mitsubishi/bang-tra-ma-loi-mitsubishi":{"id":"mitsubishi/bang-tra-ma-loi-mitsubishi","title":"B\u1EA3ng Tra C\u1EE9u To\xe0n Di\u1EC7n M\xe3 L\u1ED7i Bi\u1EBFn T\u1EA7n Mitsubishi","description":"T\xe0i li\u1EC7u n\xe0y cung c\u1EA5p B\u1EA3ng tra c\u1EE9u m\xe3 l\u1ED7i to\xe0n di\u1EC7n v\xe0 chi ti\u1EBFt nh\u1EA5t d\xe0nh cho c\xe1c d\xf2ng bi\u1EBFn t\u1EA7n Mitsubishi Electric ph\u1ED5 bi\u1EBFn t\u1EA1i Vi\u1EC7t Nam (FR-D700, FR-E700, FR-A800, FR-F800, FR-A700).","sidebar":"tutorialSidebar"},"mitsubishi/e720-mitsubishi":{"id":"mitsubishi/e720-mitsubishi","title":"T\u1ED5ng h\u1EE3p l\u1EC7nh v\xe0 tham s\u1ED1 E720 Mitsubishi","description":"T\xe0i li\u1EC7u t\u1ED5ng h\u1EE3p chi ti\u1EBFt c\xe1c m\xe3 l\u1EC7nh v\xe0 d\u1EA3i c\xe0i \u0111\u1EB7t tham s\u1ED1 c\u1EE7a d\xf2ng bi\u1EBFn t\u1EA7n Mitsubishi FR-E720 (FR-E700 Series). D\u01B0\u1EDBi \u0111\xe2y l\xe0 b\u1EA3ng tra c\u1EE9u nhanh k\xe8m gi\u1EA3i th\xedch chi ti\u1EBFt d\u1EA3i gi\xe1 tr\u1ECB \u0111\u1EC3 thu\u1EADn ti\u1EC7n cho qu\xe1 tr\xecnh c\u1EA5u h\xecnh v\xe0 v\u1EADn h\xe0nh th\u1EF1c t\u1EBF.","sidebar":"tutorialSidebar"},"mitsubishi/giam-sat-error":{"id":"mitsubishi/giam-sat-error","title":"Gi\xe1m s\xe1t v\xe0 \u0111\u1ECDc l\u1ED7i bi\u1EBFn t\u1EA7n Mitsubishi (PU & Truy\u1EC1n th\xf4ng)","description":"Trong c\xe1c h\u1EC7 th\u1ED1ng t\u1EF1 \u0111\u1ED9ng h\xf3a c\xf4ng nghi\u1EC7p, vi\u1EC7c gi\xe1m s\xe1t tr\u1EA1ng th\xe1i ho\u1EA1t \u0111\u1ED9ng v\xe0 ph\xe1t hi\u1EC7n s\u1EF1 c\u1ED1 (Fault Monitoring). Khi bi\u1EBFn t\u1EA7n g\u1EB7p s\u1EF1 c\u1ED1 (Trip), \u0111\u1ED9ng c\u01A1 s\u1EBD d\u1EEBng kh\u1EA9n c\u1EA5p \u0111\u1EC3 b\u1EA3o v\u1EC7 ph\u1EA7n c\u1EE9ng.","sidebar":"tutorialSidebar"},"mitsubishi/truyen-thong-fx3u-bien-tan":{"id":"mitsubishi/truyen-thong-fx3u-bien-tan","title":"Truy\u1EC1n th\xf4ng PLC FX3U v\u1EDBi Bi\u1EBFn t\u1EA7n Mitsubishi qua Board FX3U-485-BD (Computer Link)","description":"Trong c\xe1c h\u1EC7 th\u1ED1ng \u0111i\u1EC1u khi\u1EC3n t\u1EF1 \u0111\u1ED9ng s\u1EED d\u1EE5ng thi\u1EBFt b\u1ECB c\u1EE7a Mitsubishi Electric, gi\u1EA3i ph\xe1p k\u1EBFt n\u1ED1i gi\u1EEFa PLC FX3U v\xe0 c\xe1c d\xf2ng Bi\u1EBFn t\u1EA7n Mitsubishi (FR-A720, FR-A700, FR-E720, FR-E700, FR-D700, FR-A800, FR-F800) th\xf4ng qua board m\u1EDF r\u1ED9ng FX3U-485-BD l\xe0 gi\u1EA3i ph\xe1p c\u1EF1c k\u1EF3 ph\u1ED5 bi\u1EBFn, ti\u1EBFt ki\u1EC7m chi ph\xed d\xe2y d\u1EABn I/O v\xe0 cho ph\xe9p \u0111i\u1EC1u khi\u1EC3n, gi\xe1m s\xe1t to\xe0n di\u1EC7n t\u1EEB xa.","sidebar":"tutorialSidebar"},"omron/error-codes-omron":{"id":"omron/error-codes-omron","title":"B\u1EA3ng m\xe3 l\u1ED7i bi\u1EBFn t\u1EA7n Omron v\xe0 c\xe1ch kh\u1EAFc ph\u1EE5c","description":"Trong qu\xe1 tr\xecnh v\u1EADn h\xe0nh, bi\u1EBFn t\u1EA7n OMRON (MX2, JX, RX Series) c\xf3 th\u1EC3 g\u1EB7p s\u1EF1 c\u1ED1 v\xe0 hi\u1EC3n th\u1ECB m\xe3 l\u1ED7i (Trip) tr\xean m\xe0n h\xecnh LED. T\xe0i li\u1EC7u n\xe0y t\u1ED5ng h\u1EE3p chi ti\u1EBFt danh s\xe1ch m\xe3 l\u1ED7i, nguy\xean nh\xe2n ph\u1ED5 bi\u1EBFn v\xe0 c\xe1c b\u01B0\u1EDBc ki\u1EC3m tra, kh\u1EAFc ph\u1EE5c th\u1EF1c t\u1EBF d\xe0nh cho k\u1EF9 s\u01B0 c\u01A1 \u0111i\u1EC7n.","sidebar":"tutorialSidebar"},"omron/jx-omron":{"id":"omron/jx-omron","title":"T\u1ED5ng h\u1EE3p l\u1EC7nh v\xe0 tham s\u1ED1 3G3JX Omron","description":"T\xe0i li\u1EC7u t\u1ED5ng h\u1EE3p chi ti\u1EBFt c\xe1c m\xe3 l\u1EC7nh v\xe0 d\u1EA3i c\xe0i \u0111\u1EB7t tham s\u1ED1 c\u1EE7a d\xf2ng bi\u1EBFn t\u1EA7n Omron 3G3JX (JX Series) - d\xf2ng bi\u1EBFn t\u1EA7n c\u01A1 b\u1EA3n, nh\u1ECF g\u1ECDn v\xe0 ti\u1EBFt ki\u1EC7m chi ph\xed c\u1EE7a h\xe3ng OMRON. D\u01B0\u1EDBi \u0111\xe2y l\xe0 b\u1EA3ng tra c\u1EE9u nhanh k\xe8m gi\u1EA3i th\xedch chi ti\u1EBFt d\u1EA3i gi\xe1 tr\u1ECB ph\u1EE5c v\u1EE5 thi\u1EBFt k\u1EBF, \u0111\u1EA5u n\u1ED1i v\xe0 c\u1EA5u h\xecnh t\u1EE7 \u0111i\u1EC7n.","sidebar":"tutorialSidebar"},"omron/mx2-omron":{"id":"omron/mx2-omron","title":"T\u1ED5ng h\u1EE3p l\u1EC7nh v\xe0 tham s\u1ED1 3G3MX2 Omron","description":"T\xe0i li\u1EC7u t\u1ED5ng h\u1EE3p chi ti\u1EBFt c\xe1c m\xe3 l\u1EC7nh v\xe0 d\u1EA3i c\xe0i \u0111\u1EB7t tham s\u1ED1 c\u1EE7a d\xf2ng bi\u1EBFn t\u1EA7n Omron 3G3MX2 (MX2 Series). D\u01B0\u1EDBi \u0111\xe2y l\xe0 b\u1EA3ng tra c\u1EE9u nhanh k\xe8m gi\u1EA3i th\xedch chi ti\u1EBFt d\u1EA3i gi\xe1 tr\u1ECB gi\xfap \xedch cho qu\xe1 tr\xecnh thi\u1EBFt k\u1EBF t\u1EE7 \u0111i\u1EC7n, \u0111\u1EA5u n\u1ED1i v\xe0 c\u1EA5u h\xecnh th\u1EF1c t\u1EBF.","sidebar":"tutorialSidebar"},"wecon/error-codes-wecon":{"id":"wecon/error-codes-wecon","title":"B\u1EA3ng M\xe3 L\u1ED7i Bi\u1EBFn T\u1EA7n WECON VM V\xe0 H\u01B0\u1EDBng D\u1EABn X\u1EED L\xfd S\u1EF1 C\u1ED1 (User Manual V2.0)","description":"Khi x\u1EA3y ra s\u1EF1 c\u1ED1 trong qu\xe1 tr\xecnh v\u1EADn h\xe0nh, bi\u1EBFn t\u1EA7n WECON VM Series s\u1EBD ng\u1EAFt ng\xf5 ra \u0111\u1EC3 b\u1EA3o v\u1EC7 thi\u1EBFt b\u1ECB v\xe0 hi\u1EC3n th\u1ECB m\xe3 l\u1ED7i d\u1EA1ng ERRXX tr\xean b\xe0n ph\xedm (\u0111\u1ED3ng th\u1EDDi \u0111\xe8n ALARM nh\u1EA5p nh\xe1y).","sidebar":"tutorialSidebar"},"wecon/parameter-configuration-wecon":{"id":"wecon/parameter-configuration-wecon","title":"B\u1EA3ng M\xe3 Tham S\u1ED1 C\xe0i \u0110\u1EB7t Chi Ti\u1EBFt Bi\u1EBFn T\u1EA7n WECON VM (Function Codes F0 - FD)","description":"T\xe0i li\u1EC7u n\xe0y t\u1ED5ng h\u1EE3p to\xe0n b\u1ED9 b\u1EA3ng m\xe3 tham s\u1ED1 ch\u1EE9c n\u0103ng (Function Codes) c\u1EE7a d\xf2ng bi\u1EBFn t\u1EA7n WECON VM Series d\u1EF1a tr\xean s\u1ED5 tay h\u01B0\u1EDBng d\u1EABn ch\xednh th\u1EE9c phi\xean b\u1EA3n V2.0 (20251203).","sidebar":"tutorialSidebar"},"wecon/registers-rs485-wecon":{"id":"wecon/registers-rs485-wecon","title":"B\u1EA3n \u0110\u1ED3 Thanh Ghi & H\u01B0\u1EDBng D\u1EABn Truy\u1EC1n Th\xf4ng RS-485 Modbus RTU Bi\u1EBFn T\u1EA7n WECON VM","description":"Bi\u1EBFn t\u1EA7n WECON VM Series t\xedch h\u1EE3p s\u1EB5n c\u1ED5ng truy\u1EC1n th\xf4ng n\u1ED1i ti\u1EBFp RS-485 (h\u1ED7 tr\u1EE3 giao th\u1EE9c Modbus RTU chu\u1EA9n c\xf4ng nghi\u1EC7p). T\xednh n\u0103ng n\xe0y cho ph\xe9p \u0111i\u1EC1u khi\u1EC3n t\u1EADp trung bi\u1EBFn t\u1EA7n t\u1EEB h\u1EC7 th\u1ED1ng PLC (Siemens, Mitsubishi, Omron, WECON...) ho\u1EB7c m\xe0n h\xecnh HMI/m\xe1y t\xednh SCADA \u0111\u1EC3 \u0111\u1ECDc/ghi l\u1EC7nh v\u1EADn h\xe0nh, gi\xe1m s\xe1t th\xf4ng s\u1ED1 th\u1EDDi gian th\u1EF1c v\xe0 c\xe0i \u0111\u1EB7t tham s\u1ED1 t\u1EEB xa.","sidebar":"tutorialSidebar"},"wecon/wecon-manual":{"id":"wecon/wecon-manual","title":"S\u1ED5 Tay H\u01B0\u1EDBng D\u1EABn V\u1EADn H\xe0nh Bi\u1EBFn T\u1EA7n WECON VM Series (User Manual V2.0)","description":"Bi\u1EBFn t\u1EA7n WECON VM Series AC Drive (Phi\xean b\u1EA3n t\xe0i li\u1EC7u chu\u1EA9n V2.0) l\xe0 d\xf2ng bi\u1EBFn t\u1EA7n \u0111a n\u0103ng c\u1EE7a h\xe3ng WECON, h\u1ED7 tr\u1EE3 v\u1EADn h\xe0nh cho c\u1EA3 \u0110\u1ED9ng c\u01A1 3 pha v\xe0 \u0110\u1ED9ng c\u01A1 1 pha (Single-Phase AC Motor), t\xedch h\u1EE3p \u0111i\u1EC1u khi\u1EC3n V/F, Vector h\u1EDF v\xf2ng (Sensorless Vector Control), phanh DC, truy\u1EC1n th\xf4ng Modbus RTU v\xe0 b\u1ED9 PLC \u0111\u01A1n gi\u1EA3n 16 c\u1EA5p t\u1ED1c \u0111\u1ED9.","sidebar":"tutorialSidebar"}}}}')}}]);